CREATE TYPE public.organization_kind AS ENUM ('internal','university');
CREATE TYPE public.app_role AS ENUM ('super_admin','authorized_operator','internal_reviewer','university_administrator','registrar','iqac_manager','department_head_dean','faculty_staff_uploader','read_only_decision_maker');
CREATE TABLE public.organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 2 AND 160), kind public.organization_kind NOT NULL, code text NOT NULL UNIQUE CHECK(length(code) BETWEEN 2 AND 20), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.organizations TO authenticated; GRANT ALL ON public.organizations TO service_role;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX one_operator_organization ON public.organizations(kind) WHERE kind='internal';
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=160), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(display_name) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.organization_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE RESTRICT, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,user_id), UNIQUE(id,user_id,organization_id));
GRANT SELECT ON public.organization_memberships TO authenticated; GRANT ALL ON public.organization_memberships TO service_role;
ALTER TABLE public.organization_memberships ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE RESTRICT, membership_id uuid NOT NULL, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(membership_id,user_id,organization_id) REFERENCES public.organization_memberships(id,user_id,organization_id) ON DELETE CASCADE, UNIQUE(membership_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, organization_id uuid REFERENCES public.organizations(id) ON DELETE RESTRICT, event text NOT NULL, outcome text NOT NULL CHECK(outcome IN ('success','denied')), details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_events TO authenticated; GRANT ALL ON public.audit_events TO service_role;
ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY;
CREATE INDEX membership_user_idx ON public.organization_memberships(user_id,organization_id); CREATE INDEX role_user_idx ON public.user_roles(user_id,organization_id); CREATE INDEX audit_org_time_idx ON public.audit_events(organization_id,created_at DESC);
CREATE FUNCTION public.is_operator(_roles public.app_role[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.organization_memberships m ON m.id=r.membership_id JOIN public.organizations o ON o.id=r.organization_id WHERE r.user_id=auth.uid() AND m.active AND o.kind='internal' AND r.role=ANY(_roles)) $$;
CREATE FUNCTION public.is_member(_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.organization_memberships m JOIN public.user_roles r ON r.membership_id=m.id WHERE m.user_id=auth.uid() AND m.organization_id=_org AND m.active) $$;
CREATE FUNCTION public.can_manage(_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_operator(ARRAY['super_admin']::public.app_role[]) OR EXISTS(SELECT 1 FROM public.user_roles r JOIN public.organization_memberships m ON m.id=r.membership_id JOIN public.organizations o ON o.id=r.organization_id WHERE r.user_id=auth.uid() AND r.organization_id=_org AND m.active AND o.kind='university' AND r.role='university_administrator') $$;
CREATE FUNCTION public.can_read_org(_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_member(_org) OR public.is_operator(ARRAY['super_admin','authorized_operator']::public.app_role[]) $$;
REVOKE ALL ON FUNCTION public.is_operator(public.app_role[]),public.is_member(uuid),public.can_manage(uuid),public.can_read_org(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.is_operator(public.app_role[]),public.is_member(uuid),public.can_manage(uuid),public.can_read_org(uuid) TO authenticated,service_role;
CREATE POLICY organization_read ON public.organizations FOR SELECT TO authenticated USING(public.can_read_org(id));
CREATE POLICY organization_create ON public.organizations FOR INSERT TO authenticated WITH CHECK(kind='university' AND public.is_operator(ARRAY['super_admin']::public.app_role[]));
CREATE POLICY organization_update ON public.organizations FOR UPDATE TO authenticated USING(public.can_manage(id)) WITH CHECK(public.can_manage(id));
CREATE POLICY own_profile ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR EXISTS(SELECT 1 FROM public.organization_memberships m WHERE m.user_id=profiles.id AND public.can_manage(m.organization_id)));
CREATE POLICY update_own_profile ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY membership_read ON public.organization_memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.can_manage(organization_id));
CREATE POLICY role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.can_manage(organization_id));
CREATE POLICY audit_read ON public.audit_events FOR SELECT TO authenticated USING(public.can_manage(organization_id) OR (public.is_member(organization_id) AND public.is_operator(ARRAY['internal_reviewer']::public.app_role[])));
CREATE FUNCTION public.validate_org_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.kind<>OLD.kind OR NEW.code<>OLD.code THEN RAISE EXCEPTION 'Organization identity is immutable'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER org_identity BEFORE UPDATE ON public.organizations FOR EACH ROW EXECUTE FUNCTION public.validate_org_update();
CREATE FUNCTION public.validate_role_kind() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE k public.organization_kind; BEGIN SELECT kind INTO k FROM public.organizations WHERE id=NEW.organization_id; IF (k='internal') <> (NEW.role IN ('super_admin','authorized_operator','internal_reviewer')) THEN RAISE EXCEPTION 'Role does not belong to organization type'; END IF; RETURN NEW; END $$;
CREATE TRIGGER role_kind BEFORE INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.validate_role_kind();
CREATE FUNCTION public.create_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',NEW.raw_user_meta_data->>'name',''),160)); RETURN NEW; END $$;
CREATE TRIGGER iiaf_user_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();
CREATE FUNCTION public.audit_admin_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE row_data jsonb; org uuid; BEGIN row_data=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END; org=CASE WHEN TG_TABLE_NAME='organizations' THEN (row_data->>'id')::uuid ELSE (row_data->>'organization_id')::uuid END; INSERT INTO public.audit_events(actor_id,organization_id,event,outcome,details) VALUES(auth.uid(),org,TG_TABLE_NAME||'.'||lower(TG_OP),'success',jsonb_build_object('record_id',row_data->>'id','role',row_data->>'role','active',row_data->>'active')); RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
CREATE TRIGGER organization_audit AFTER INSERT OR UPDATE ON public.organizations FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change(); CREATE TRIGGER membership_audit AFTER INSERT OR UPDATE OR DELETE ON public.organization_memberships FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change(); CREATE TRIGGER roles_audit AFTER INSERT OR UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE FUNCTION public.set_member_role(_org uuid,_user uuid,_role public.app_role,_active boolean DEFAULT true) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mid uuid; k public.organization_kind; BEGIN IF NOT public.can_manage(_org) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; SELECT kind INTO k FROM public.organizations WHERE id=_org; IF k='internal' AND NOT public.is_operator(ARRAY['super_admin']::public.app_role[]) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=_user AND r.role='super_admin') AND (NOT _active OR _role<>'super_admin') AND NOT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.organization_memberships m ON m.id=r.membership_id WHERE r.role='super_admin' AND m.active AND r.user_id<>_user) THEN RAISE EXCEPTION 'Cannot remove the last Super Admin'; END IF; INSERT INTO public.organization_memberships(organization_id,user_id,active) VALUES(_org,_user,_active) ON CONFLICT(organization_id,user_id) DO UPDATE SET active=EXCLUDED.active RETURNING id INTO mid; DELETE FROM public.user_roles WHERE membership_id=mid; INSERT INTO public.user_roles(user_id,organization_id,membership_id,role) VALUES(_user,_org,mid,_role); END $$;
REVOKE ALL ON FUNCTION public.set_member_role(uuid,uuid,public.app_role,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_member_role(uuid,uuid,public.app_role,boolean) TO authenticated;
CREATE FUNCTION public.record_security_event(_org uuid,_event text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_member(_org) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; IF _event NOT IN ('session.sign_in','session.sign_out','workspace.selected') THEN RAISE EXCEPTION 'Invalid event'; END IF; INSERT INTO public.audit_events(actor_id,organization_id,event,outcome) VALUES(auth.uid(),_org,_event,'success'); END $$;
REVOKE ALL ON FUNCTION public.record_security_event(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_security_event(uuid,text) TO authenticated;
CREATE FUNCTION public.bootstrap_operator(_user uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid; mid uuid; BEGIN PERFORM pg_advisory_xact_lock(120261020); IF EXISTS(SELECT 1 FROM public.user_roles WHERE role='super_admin') THEN RAISE EXCEPTION 'First operator already provisioned'; END IF; IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=_user AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'A confirmed account is required'; END IF; INSERT INTO public.organizations(name,kind,code) VALUES('Rafts and Rivers','internal','RR') RETURNING id INTO oid; INSERT INTO public.organization_memberships(organization_id,user_id) VALUES(oid,_user) RETURNING id INTO mid; INSERT INTO public.user_roles(user_id,organization_id,membership_id,role) VALUES(_user,oid,mid,'super_admin'); INSERT INTO public.audit_events(actor_id,organization_id,event,outcome,details) VALUES(_user,oid,'operator.bootstrap','success',jsonb_build_object('provisioning','trusted administrator')); RETURN oid; END $$;
REVOKE ALL ON FUNCTION public.bootstrap_operator(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.bootstrap_operator(uuid) TO service_role;
REVOKE ALL ON FUNCTION public.create_user_profile(),public.audit_admin_change(),public.validate_org_update(),public.validate_role_kind() FROM PUBLIC,anon,authenticated;
COMMENT ON TABLE public.organizations IS 'Phase 1 organization identity; university institutional evidence remains demonstration-only'; COMMENT ON TABLE public.user_roles IS 'Protected organization-scoped roles, never derived from editable profile metadata'; COMMENT ON TABLE public.audit_events IS 'Administrative database changes and app session events only; auth failures are provider logs';